('072144c9-2550-4790-8935-4d4e01e2d16e','press-release-kit','Press Release','document',1240,1754,'[{"id":"p1","background":{"type":"solid","color":"#FFFFFF"},"elements":[{"id":"rect_mvv4692zf6v59jr","type":"rect","x":0,"y":0,"width":1240,"height":16,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"fill":"#8C2F39","stroke":"transparent","strokeWidth":0,"cornerRadius":24},{"id":"text_mvv4692zf71tmt7","type":"text","x":100,"y":90,"width":900,"height":70,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"FOR IMMEDIATE RELEASE","fontSize":34,"fontFamily":"Archivo","bold":true,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#8C2F39","align":"left","lineHeight":1.25,"letterSpacing":4},{"id":"line_mvv4692zf8gxhrn","type":"line","x":100,"y":180,"width":1040,"height":0,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"stroke":"#D9C5C0","strokeWidth":2,"dashed":false,"arrowStart":false,"arrowEnd":false},{"id":"text_mvv4692zf9mojpc","type":"text","x":100,"y":230,"width":1040,"height":180,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Canvix hits one million designs created","fontSize":72,"fontFamily":"Playfair Display","bold":false,"italic":false,"underline":false,"strike":false,"uppercase":false,"fill":"#1A1A1A","align":"left","lineHeight":1.2,"letterSpacing":0},{"id":"text_mvv4692zfa510vl","type":"text","x":100,"y":460,"width":1040,"height":90,"rotation":0,"opacity":1,"locked":false,"visible":true,"shadow":{"enabled":false,"color":"#000000","blur":12,"offsetX":0,"offsetY":6},"text":"Community-driven design tool reaches milestone in 14 months, staying 100% free","fontSize":32,"fontFamily":"Inter","bol